import test from 'node:test';
import assert from 'node:assert/strict';
import {
  verifyPassword,
  hashPassword,
  passwordFingerprint,
  urlsafeBase64Encode,
  urlsafeBase64Decode,
  makePasswordResetToken,
  checkPasswordResetToken,
} from '../src/utils/passwords.js';

test('verifyPassword handles Django PBKDF2 SHA-256 hashes correctly', () => {
  // Hash generated by Django: pbkdf2_sha256$1200000$testSalt123$ThWFGwuJb8JkWV5XsFWnF4yTCh28BGOdemsDjBKSPN8= for 'password123'
  const djangoHash = 'pbkdf2_sha256$1200000$testSalt123$ThWFGwuJb8JkWV5XsFWnF4yTCh28BGOdemsDjBKSPN8=';

  assert.equal(verifyPassword('password123', djangoHash), true);
  assert.equal(verifyPassword('wrongpassword', djangoHash), false);
  assert.equal(verifyPassword('', djangoHash), false);
});

test('hashPassword creates valid bcrypt hash and verifyPassword verifies it', () => {
  const plain = 'MinhaS3nhaForte!2026';
  const hashed = hashPassword(plain);

  assert.ok(hashed.startsWith('$2a$') || hashed.startsWith('$2b$'));
  assert.equal(verifyPassword(plain, hashed), true);
  assert.equal(verifyPassword('outrasenha', hashed), false);
});

test('passwordFingerprint matches SHA-256 of password hash', () => {
  const hash = 'pbkdf2_sha256$1200000$test$abc';
  const fp1 = passwordFingerprint(hash);
  const fp2 = passwordFingerprint(hash);

  assert.equal(fp1, fp2);
  assert.equal(typeof fp1, 'string');
  assert.equal(fp1.length, 64); // SHA-256 hex length
});

test('urlsafeBase64Encode and urlsafeBase64Decode roundtrip user id', () => {
  assert.equal(urlsafeBase64Encode(1), 'MQ');
  assert.equal(urlsafeBase64Decode('MQ'), '1');
  assert.equal(urlsafeBase64Decode(urlsafeBase64Encode(12345)), '12345');
});

test('makePasswordResetToken and checkPasswordResetToken validate and expire correctly', () => {
  const user = { id: 42, password: 'stored-password-hash' };
  const secret = 'super-secret-test-key-32-chars-minimum';

  const token = makePasswordResetToken(user, secret);
  assert.equal(typeof token, 'string');

  // Valid token check
  assert.equal(checkPasswordResetToken(user, token, secret, 3600), true);

  // Invalidate on changed password
  const updatedUser = { id: 42, password: 'new-password-hash' };
  assert.equal(checkPasswordResetToken(updatedUser, token, secret, 3600), false);

  // Invalidate on wrong token
  assert.equal(checkPasswordResetToken(user, 'invalid-token', secret, 3600), false);
});

